===== FILE: index.html =====
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>快送外卖 - 成都本地美食配送</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
            color: #333;
            background: #f8f9fa;
            line-height: 1.6;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        .header {
            background: #fff;
            border-bottom: 1px solid #eee;
            position: sticky;
            top: 0;
            z-index: 100;
            box-shadow: 0 2px 8px rgba(0,0,0,0.04);
        }

        .header-inner {
            max-width: 1200px;
            margin: 0 auto;
            padding: 16px 24px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 24px;
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 10px;
            font-size: 22px;
            font-weight: 700;
            color: #e63e1e;
            flex-shrink: 0;
        }

        .logo-icon {
            width: 38px;
            height: 38px;
            background: #e63e1e;
            border-radius: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #fff;
            font-size: 20px;
        }

        .search-box {
            flex: 1;
            max-width: 480px;
            position: relative;
        }

        .search-box input {
            width: 100%;
            padding: 12px 44px 12px 16px;
            border: 2px solid #e8e8e8;
            border-radius: 10px;
            font-size: 15px;
            outline: none;
            transition: border-color 0.2s;
        }

        .search-box input:focus {
            border-color: #e63e1e;
        }

        .search-btn {
            position: absolute;
            right: 6px;
            top: 50%;
            transform: translateY(-50%);
            width: 34px;
            height: 34px;
            background: #e63e1e;
            border: none;
            border-radius: 8px;
            color: #fff;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 16px;
        }

        .header-actions {
            display: flex;
            align-items: center;
            gap: 16px;
            flex-shrink: 0;
        }

        .loc-btn {
            display: flex;
            align-items: center;
            gap: 6px;
            padding: 8px 14px;
            border: 1px solid #e0e0e0;
            border-radius: 8px;
            font-size: 14px;
            cursor: pointer;
            background: #fff;
            color: #555;
        }

        .cart-btn {
            display: flex;
            align-items: center;
            gap: 6px;
            padding: 8px 16px;
            background: #e63e1e;
            color: #fff;
            border-radius: 8px;
            font-size: 14px;
            cursor: pointer;
            border: none;
            font-weight: 500;
        }

        .cart-count {
            background: #fff;
            color: #e63e1e;
            width: 20px;
            height: 20px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            font-weight: 700;
        }

        .nav-bar {
            background: #fff;
            border-bottom: 1px solid #f0f0f0;
        }

        .nav-inner {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 24px;
            display: flex;
            gap: 32px;
        }

        .nav-link {
            padding: 12px 0;
            font-size: 14px;
            color: #666;
            position: relative;
        }

        .nav-link:hover, .nav-link.active {
            color: #e63e1e;
        }

        .nav-link.active::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: 2px;
            background: #e63e1e;
            border-radius: 1px;
        }

        .hero {
            background: linear-gradient(135deg, #fff5f0 0%, #fff 100%);
            padding: 48px 24px;
        }

        .hero-inner {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 40px;
        }

        .hero-text h1 {
            font-size: 36px;
            color: #222;
            margin-bottom: 12px;
            font-weight: 700;
        }

        .hero-text p {
            font-size: 16px;
            color: #777;
            margin-bottom: 24px;
        }

        .hero-stats {
            display: flex;
            gap: 32px;
        }

        .stat-item {
            text-align: center;
        }

        .stat-num {
            font-size: 28px;
            font-weight: 700;
            color: #e63e1e;
        }

        .stat-label {
            font-size: 13px;
            color: #999;
            margin-top: 4px;
        }

        .hero-visual {
            width: 280px;
            height: 280px;
            background: linear-gradient(135deg, #ffe8e0, #fff5f0);
            border-radius: 24px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 100px;
            flex-shrink: 0;
        }

        .section {
            max-width: 1200px;
            margin: 0 auto;
            padding: 48px 24px;
        }

        .section-title {
            font-size: 24px;
            font-weight: 700;
            color: #222;
            margin-bottom: 24px;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .section-title a {
            font-size: 14px;
            color: #e63e1e;
            font-weight: 400;
        }

        .category-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 20px;
        }

        .category-card {
            background: #fff;
            border-radius: 16px;
            padding: 28px 20px;
            text-align: center;
            cursor: pointer;
            transition: all 0.2s;
            border: 1px solid #f0f0f0;
        }

        .category-card:hover {
            transform: translateY(-3px);
            box-shadow: 0 8px 24px rgba(230, 62, 30, 0.1);
            border-color: #ffe0d6;
        }

        .category-icon {
            width: 56px;
            height: 56px;
            margin: 0 auto 14px;
            border-radius: 14px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 28px;
        }

        .cat-sichuan { background: #fff0ed; }
        .cat-hotpot { background: #fff8f0; }
        .cat-noodle { background: #f0fff4; }
        .cat-fast { background: #f5f0ff; }
        .cat-light { background: #f0fff8; }
        .cat-drink { background: #fff5f5; }
        .cat-bbq { background: #fffcf0; }
        .cat-dessert { background: #fff0f8; }

        .category-name {
            font-size: 15px;
            font-weight: 600;
            color: #333;
            margin-bottom: 4px;
        }

        .category-count {
            font-size: 12px;
            color: #999;
        }

        .featured-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 20px;
        }

        .rest-card {
            background: #fff;
            border-radius: 14px;
            overflow: hidden;
            cursor: pointer;
            transition: all 0.2s;
            border: 1px solid #f0f0f0;
        }

        .rest-card:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(0,0,0,0.08);
        }

        .rest-img {
            height: 160px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 56px;
        }

        .rest-img-1 { background: linear-gradient(135deg, #fff5f0, #ffe8dd); }
        .rest-img-2 { background: linear-gradient(135deg, #f0fff5, #e0ffe8); }
        .rest-img-3 { background: linear-gradient(135deg, #fff8f0, #fff0e0); }

        .rest-info {
            padding: 16px;
        }

        .rest-name {
            font-size: 16px;
            font-weight: 600;
            color: #222;
            margin-bottom: 6px;
        }

        .rest-meta {
            display: flex;
            align-items: center;
            gap: 12px;
            font-size: 13px;
            color: #888;
            margin-bottom: 8px;
        }

        .rest-tag {
            font-size: 11px;
            padding: 2px 8px;
            border-radius: 4px;
            background: #fff0ed;
            color: #e63e1e;
            font-weight: 500;
        }

        .rest-rating {
            color: #ff9800;
            font-weight: 600;
        }

        .rest-bottom {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .rest-price {
            font-size: 14px;
            color: #e63e1e;
            font-weight: 600;
        }

        .rest-deliver {
            font-size: 12px;
            color: #999;
        }

        .banner {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 24px 48px;
        }

        .banner-inner {
            background: linear-gradient(135deg, #e63e1e, #ff6b35);
            border-radius: 16px;
            padding: 32px 40px;
            color: #fff;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .banner-text h3 {
            font-size: 22px;
            margin-bottom: 8px;
        }

        .banner-text p {
            font-size: 14px;
            opacity: 0.9;
        }

        .banner-btn {
            background: #fff;
            color: #e63e1e;
            padding: 10px 24px;
            border-radius: 8px;
            font-weight: 600;
            font-size: 14px;
            cursor: pointer;
            border: none;
            white-space: nowrap;
        }

        .footer {
            background: #222;
            color: #aaa;
            padding: 40px 24px 24px;
        }

        .footer-inner {
            max-width: 1200px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 40px;
            padding-bottom: 32px;
            border-bottom: 1px solid #333;
        }

        .footer-brand h4 {
            color: #fff;
            font-size: 18px;
            margin-bottom: 12px;
        }

        .footer-brand p {
            font-size: 13px;
            line-height: 1.8;
        }

        .footer-col h5 {
            color: #fff;
            font-size: 14px;
            margin-bottom: 12px;
        }

        .footer-col a {
            display: block;
            font-size: 13px;
            color: #999;
            margin-bottom: 8px;
        }

        .footer-col a:hover {
            color: #fff;
        }

        .footer-bottom {
            max-width: 1200px;
            margin: 0 auto;
            padding-top: 20px;
            font-size: 12px;
            text-align: center;
            color: #666;
        }

        @media (max-width: 900px) {
            .hero-inner {
                flex-direction: column;
                text-align: center;
            }
            .hero-stats {
                justify-content: center;
            }
            .category-grid {
                grid-template-columns: repeat(3, 1fr);
            }
            .featured-grid {
                grid-template-columns: repeat(2, 1fr);
            }
            .footer-inner {
                grid-template-columns: 1fr 1fr;
            }
            .header-inner {
                flex-wrap: wrap;
            }
            .search-box {
                order: 3;
                max-width: 100%;
                width: 100%;
            }
        }

        @media (max-width: 600px) {
            .category-grid {
                grid-template-columns: repeat(2, 1fr);
            }
            .featured-grid {
                grid-template-columns: 1fr;
            }
            .banner-inner {
                flex-direction: column;
                text-align: center;
                gap: 16px;
            }
            .footer-inner {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
